(5278803, 768012, 18655, '<td valign="top">Interesting angle that works well. Good job!</td>', 'Interesting angle that works well. Good job!', '2009-02-28 06:49:14.000000', NULL, 1),
(5278804, 767990, 18655, '<td valign="top">A little blurry but good action shot. 6</td>', 'A little blurry but good action shot. 6', '2009-02-28 06:49:28.000000', NULL, 1),
(5278805, 768067, 18655, '<td valign="top">Great shot and fun to look at. Lacking a little context maybe but looks good anyway.</td>', 'Great shot and fun to look at. Lacking a little context maybe but looks good anyway.', '2009-02-28 06:51:29.000000', NULL, 1),
(5278806, 767957, 18655, '<td valign="top">Good job with the tilted horizon. Good action scene.</td>', 'Good job with the tilted horizon. Good action scene.', '2009-02-28 06:52:04.000000', NULL, 1),
(5278807, 768158, 18655, '<td valign="top">Fun and unusual. I don''t mind the act they are doing but this is not a nice photo that I would have displayed on the wall in my dining room exactly :)<br/> <br/>Good idea though and I''ll give you an extra point for creativity.</td>', 'Fun and unusual. I don''t mind the act they are doing but this is not a nice photo that I would have displayed on the wall in my dining room exactly :) Good idea though and I''ll give you an extra point for creativity.', '2009-02-28 06:55:35.000000', NULL, 1),
(5278808, 767172, 18655, '<td valign="top">Looks good. I was going to submit a snow boarder in the air picture myself but thought it was too boring in the end. The big "E" adds another element to it thought and I like it. 7</td>', 'Looks good. I was going to submit a snow boarder in the air picture myself but thought it was too boring in the end. The big "E" adds another element to it thought and I like it. 7', '2009-02-28 06:57:03.000000', NULL, 1),
(5278809, 768269, 18655, '<td valign="top">A real cutie! Good capture.</td>', 'A real cutie! Good capture.', '2009-02-28 06:58:33.000000', NULL, 1),
(5278810, 768065, 18655, '<td valign="top">And the colors are not dull either. Very sharp and vivid. Tells a story on its own and the background plus tilted appearance is suitable. <br/> <br/>This is much more than a family type picture to me. 8</td>', 'And the colors are not dull either. Very sharp and vivid. Tells a story on its own and the background plus tilted appearance is suitable.  This is much more than a family type picture to me. 8', '2009-02-28 07:00:43.000000', NULL, 1),
(5278811, 768181, 18655, '<td valign="top">Great shot! Looks very good in b/w and definitely gives a good impression of action. 8</td>', 'Great shot! Looks very good in b/w and definitely gives a good impression of action. 8', '2009-02-28 07:01:35.000000', NULL, 1),
(5278813, 768266, 18655, '<td valign="top">Good crop - looks good in b/w. The jockey''s standing position gives it an expression of action. 7</td>', 'Good crop - looks good in b/w. The jockey''s standing position gives it an expression of action. 7', '2009-02-28 07:02:59.000000', NULL, 1),
(5278814, 768210, 18655, '<td valign="top">Good exposure level and excellent contrasts. Looks like a million bucks in b/w and definitely expresses action. Much more to be said but I''m sure you''ll get a couple dozen comments on this. 10+</td>', 'Good exposure level and excellent contrasts. Looks like a million bucks in b/w and definitely expresses action. Much more to be said but I''m sure you''ll get a couple dozen comments on this. 10+', '2009-02-28 07:04:50.000000', NULL, 1),
(5278816, 768177, 18655, '<td valign="top">A little blurry but the content is excellent.</td>', 'A little blurry but the content is excellent.', '2009-02-28 07:05:18.000000', NULL, 1),
(5278819, 768145, 18655, '<td valign="top">I wish the boy had been a little less blurred but otherwise a good shot with vivid colors.</td>', 'I wish the boy had been a little less blurred but otherwise a good shot with vivid colors.', '2009-02-28 07:06:13.000000', NULL, 1),
(5278822, 768053, 18655, '<td valign="top">Excellent illusion (I certainly hope it''s not for real!!). Post editing is tastefully executed. 8</td>', 'Excellent illusion (I certainly hope it''s not for real!!). Post editing is tastefully executed. 8', '2009-02-28 07:07:43.000000', NULL, 1),
(5278824, 768136, 18655, '<td valign="top">Good idea and well executed as far as I can see but I don''t find the picture itself to be very attractive. 5</td>', 'Good idea and well executed as far as I can see but I don''t find the picture itself to be very attractive. 5', '2009-02-28 07:08:45.000000', NULL, 1),
(5278825, 767914, 18655, '<td valign="top">Great capture. In focus and sharp with strong colors. Definitely action. 7</td>', 'Great capture. In focus and sharp with strong colors. Definitely action. 7', '2009-02-28 07:10:13.000000', NULL, 1),
(5278826, 768249, 18655, '<td valign="top">Cool, interesting, well executed and fun. I don''t really like looking at it though and I would never display it anywhere. But it is fun. 6</td>', 'Cool, interesting, well executed and fun. I don''t really like looking at it though and I would never display it anywhere. But it is fun. 6', '2009-02-28 07:12:05.000000', NULL, 1),
(5278827, 767899, 18655, '<td valign="top">A little messy but otherwise good.</td>', 'A little messy but otherwise good.', '2009-02-28 07:13:26.000000', NULL, 1),
(5278828, 766892, 18655, '<td valign="top">Excellent Vegas shot that conveys action in its own way. Vegas is after all the action city. 7</td>', 'Excellent Vegas shot that conveys action in its own way. Vegas is after all the action city. 7', '2009-02-28 07:15:09.000000', NULL, 1),
(5278830, 768004, 18655, '<td valign="top">Probably a few technical aspects here that are not spot on. But I don''t think any photo that follow the book in all ways will ever be looked at as creative or exciting the same way this does.<br/>I love the overall look. The blurry effect, the fact that the crowd is ecstatic but still not stealing from the rider makes this look very good. I could easily see this shot in a book with famous moments in the history of sport.<br/> <br/>The image the way it is taken makes me look at it for a long time. Studying all the details and feeling the moment. The rider is also standing which makes it clear that he is giving 150% and going for gold. The crop is exactly where it should be leaving room forward.<br/> <br/>Great action shot! 10+</td>', 'Probably a few technical aspects here that are not spot on. But I don''t think any photo that follow the book in all ways will ever be looked at as creative or exciting the same way this does.I love the overall look. The blurry effect, the fact that the crowd is ecstatic but still not stealing from the rider makes this look very good. I could easily see this shot in a book with famous moments in the history of sport. The image the way it is taken makes me look at it for a long time. Studying all the details and feeling the moment. The rider is also standing which makes it clear that he is giving 150% and going for gold. The crop is exactly where it should be leaving room forward. Great action shot! 10+', '2009-02-28 07:23:25.000000', NULL, 1),
(5278831, 768252, 18655, '<td valign="top">great action shot. Good colors and sharp.</td>', 'great action shot. Good colors and sharp.', '2009-02-28 07:23:54.000000', NULL, 1),
(5278832, 768051, 18655, '<td valign="top">A little fake looking and unnatural colors on my particular monitor but the overall image looks good.</td>', 'A little fake looking and unnatural colors on my particular monitor but the overall image looks good.', '2009-02-28 07:25:00.000000', NULL, 1),
(5278833, 767213, 18655, '<td valign="top">Everything is very sharp and contrasty. It is very pleasing to look at. At the same time, the guy almost does not look real. It looks like he is totally frozen in time. It IS a very pretty shot and although I know there is plenty of action, it does not express action very well. 7</td>', 'Everything is very sharp and contrasty. It is very pleasing to look at. At the same time, the guy almost does not look real. It looks like he is totally frozen in time. It IS a very pretty shot and although I know there is plenty of action, it does not express action very well. 7', '2009-02-28 07:29:59.000000', NULL, 1),
(5278834, 768057, 18655, '<td valign="top">He looks a little frozen in movement and it would have looked good if the shutter time had been a wee bit longer. The content and picture otherwise is good. 6</td>', 'He looks a little frozen in movement and it would have looked good if the shutter time had been a wee bit longer. The content and picture otherwise is good. 6', '2009-02-28 07:30:53.000000', NULL, 1),
(5278836, 767241, 18655, '<td valign="top">Well executed and fun to look at. 9</td>', 'Well executed and fun to look at. 9', '2009-02-28 07:33:36.000000', NULL, 1),
(5278837, 767228, 18655, '<td valign="top">Great job. Definitely conveys action and the yellow outfits really make it stand out. 8</td>', 'Great job. Definitely conveys action and the yellow outfits really make it stand out. 8', '2009-02-28 07:34:46.000000', NULL, 1),
(5278838, 767450, 18655, '<td valign="top">The trees in the background steals a little from the rider but otherwise well executed and a nice looking image.</td>', 'The trees in the background steals a little from the rider but otherwise well executed and a nice looking image.', '2009-02-28 07:36:54.000000', NULL, 1),
(5278839, 768015, 18655, '<td valign="top">Sharp and well executed. Good background to make the athlete stand out. 8</td>', 'Sharp and well executed. Good background to make the athlete stand out. 8', '2009-02-28 07:40:33.000000', NULL, 1),
(5278840, 766506, 18655, '<td valign="top">Excellent! Good balance and interesting to look at. Suitable and good expression. Lighting is impeccable. 10</td>', 'Excellent! Good balance and interesting to look at. Suitable and good expression. Lighting is impeccable. 10', '2009-02-28 07:42:24.000000', NULL, 1),
(5278842, 767500, 18655, '<td valign="top">OOOoh - crappy! I flown Texans myself and know how easily they ground loop. The center of gravity is just too high for a tail dragger. In this incident since the prop touched ground; the engine has to be pulled and completely overhauled. BIG bucks!!<br/>Good capture though and a good sense of action!</td>', 'OOOoh - crappy! I flown Texans myself and know how easily they ground loop. The center of gravity is just too high for a tail dragger. In this incident since the prop touched ground; the engine has to be pulled and completely overhauled. BIG bucks!!Good capture though and a good sense of action!', '2009-02-28 07:46:11.000000', NULL, 1),
(5278845, 768053, 100393, '<td valign="top">OK, I''ll come back and vote later but I have a ton of concerns with this image.<br/> <br/>I''m asking myself is this done for real? If so, I find it to be spectacularly irresponsible.<br/> <br/>If not, then this is masterfully contrived.<br/> <br/>Photographically - technically and in terms of visual impact it is pretty amazing but I feel I just can''t condone what I''m seeing. I''ll wait for a few days perhaps before I decide to vote on it or not.<br/> <br/>Back to vote - I''ve decided that I''ve registered my concerns and that''ll I''ll put them aside. As I said before, this is very competent work  - 8.</td>', 'OK, I''ll come back and vote later but I have a ton of concerns with this image. I''m asking myself is this done for real? If so, I find it to be spectacularly irresponsible. If not, then this is masterfully contrived. Photographically - technically and in terms of visual impact it is pretty amazing but I feel I just can''t condone what I''m seeing. I''ll wait for a few days perhaps before I decide to vote on it or not. Back to vote - I''ve decided that I''ve registered my concerns and that''ll I''ll put them aside. As I said before, this is very competent work  - 8.', '2009-02-28 07:59:25.000000', NULL, 1),
(5278924, 767944, 103153, '<td valign="top">Good shot! I love the lighting, and the not-perfectly-straight-on angle keeps it from being cliche.</td>', 'Good shot! I love the lighting, and the not-perfectly-straight-on angle keeps it from being cliche.', '2009-02-28 10:33:37.000000', NULL, 1),
(5278926, 768148, 103153, '<td valign="top">I had trouble picking out the flapjack, or whatever it is. Maybe crop more?</td>', 'I had trouble picking out the flapjack, or whatever it is. Maybe crop more?', '2009-02-28 10:34:49.000000', NULL, 1),
(5278928, 768122, 103153, '<td valign="top">What is the point of the "action"? Nothing is in focus, no story, no striking visual, I don''t get it.</td>', 'What is the point of the "action"? Nothing is in focus, no story, no striking visual, I don''t get it.', '2009-02-28 10:38:45.000000', NULL, 1),
(5278929, 768252, 103153, '<td valign="top">I''m a sucker for kayak water polo.</td>', 'I''m a sucker for kayak water polo.', '2009-02-28 10:39:56.000000', NULL, 1),
(5278931, 767584, 103153, '<td valign="top">Nice focus. Maybe crop off the left side tighter?</td>', 'Nice focus. Maybe crop off the left side tighter?', '2009-02-28 10:43:03.000000', NULL, 1),
(5278933, 768104, 103153, '<td valign="top">Nice idea, but without the title, I couldn''t be sure it was an ax. Why is the grass the only ting in focus?</td>', 'Nice idea, but without the title, I couldn''t be sure it was an ax. Why is the grass the only ting in focus?', '2009-02-28 10:45:58.000000', NULL, 1),
(5278934, 768188, 103153, '<td valign="top">Nice, but the people milling around in back keep it from being a winner.</td>', 'Nice, but the people milling around in back keep it from being a winner.', '2009-02-28 10:47:35.000000', NULL, 1),
(5278936, 768103, 103153, '<td valign="top">Stunning.</td>', 'Stunning.', '2009-02-28 10:48:49.000000', NULL, 1),
(5278938, 766493, 103153, '<td valign="top">Accidentally hit the button?</td>', 'Accidentally hit the button?', '2009-02-28 10:52:30.000000', NULL, 1),
