(5285531, 768177, 99506, '<td valign="top">Now this takes the water droplet shot and puts it in a totally different light. The B&amp;W works well, I would have prefered it if the child wasn''t right in the middle of the frame but I stil love it 9</td>', 'Now this takes the water droplet shot and puts it in a totally different light. The B&W works well, I would have prefered it if the child wasn''t right in the middle of the frame but I stil love it 9', '2009-03-03 10:42:29.000000', NULL, 1),
(5285534, 767957, 99506, '<td valign="top">I think he only thing wrong here is that there is no impression of movement.<br/>If you had tracked the cars so that the background was blured it would have been better IMO, but still a nice shot.</td>', 'I think he only thing wrong here is that there is no impression of movement.If you had tracked the cars so that the background was blured it would have been better IMO, but still a nice shot.', '2009-03-03 10:44:34.000000', NULL, 1),
(5285536, 768184, 99506, '<td valign="top">Very striking but a bit over processed for my liking.</td>', 'Very striking but a bit over processed for my liking.', '2009-03-03 10:45:16.000000', NULL, 1),
(5285540, 767811, 99506, '<td valign="top">Spot on. Great use of colour love it</td>', 'Spot on. Great use of colour love it', '2009-03-03 10:46:19.000000', NULL, 1),
