(5285545, 768251, 99506, '<td valign="top">This has a great feel of motion I really like it but i really dont like the boarder.</td>', 'This has a great feel of motion I really like it but i really dont like the boarder.', '2009-03-03 10:50:24.000000', NULL, 1),
(5285547, 767145, 99506, '<td valign="top">OMG!</td>', 'OMG!', '2009-03-03 10:50:50.000000', NULL, 1),
