(5285993, 768035, 84668, '<td valign="top">For my taste, I''d try to focus either the guy or his hand with the ball, also use a faster shutter speed to avoid the very blurry look of the image. The way it is, it''s so much blurry, and looking completely out of focus.</td>', 'For my taste, I''d try to focus either the guy or his hand with the ball, also use a faster shutter speed to avoid the very blurry look of the image. The way it is, it''s so much blurry, and looking completely out of focus.', '2009-03-03 17:06:01.000000', NULL, 1),
(5286048, 767628, 23430, '<td valign="top">Like the pair in unison. Good focus. Not saying you can avoid it but the hay on the track disrupts the background a bit. Good shot all round.</td>', 'Like the pair in unison. Good focus. Not saying you can avoid it but the hay on the track disrupts the background a bit. Good shot all round.', '2009-03-03 17:44:39.000000', NULL, 1),
